/**
 * Weekly and monthly reports of the blood pressure and blood sugar logs, for the person's own records
 * or to bring to a check-up. Pure functions (no React, no I/O), so they are unit-tested: the period
 * maths, the per-marker summary, the printable HTML (rendered to PDF on the phone) and the plain-text
 * email body. Every number comes from the recorded readings; nothing is generated by a model.
 */
import { linearTrend, mean } from '../domain/stats';
import { addDays, formatDateTime, formatLocalDate, formatLocalDateKey, localDateKey, parseLocalDate, startOfLocalDay, weekdayOf } from '../domain/time';
import type { ClinicianTarget, LocalDate, Profile, VitalReading } from '../domain/types';
import { sparkGeometry, type SparkPoint } from '../ui/sparkGeometry';
import { TREND_THRESHOLD, VITAL_META, assessReading, contextLabel, displayUnit, formatDisplay, positionPill, readingDisplay, toDisplay, trendWords } from '../ui/vitals';

export type ReportKind = 'weekly' | 'monthly';
export type ReportMarker = 'blood_pressure' | 'glucose';
export const REPORT_MARKERS: ReportMarker[] = ['blood_pressure', 'glucose'];

/** Settings key for the email address reports go to, per profile (stored on this device only). */
export const reportEmailKey = (profileId: string): string => `report_email:${profileId}`;

export function isValidEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim());
}

export interface ReportPeriod {
  kind: ReportKind;
  /** First and last local calendar days (inclusive). */
  startDate: LocalDate;
  endDate: LocalDate;
  /** Instants: start inclusive, end exclusive. */
  start: number;
  end: number;
  label: string;
  /** False while the period is still running (this week or this month). */
  complete: boolean;
}

/**
 * The calendar week (Monday to Sunday) or month containing today, moved by `offset` periods
 * (0 = current, -1 = previous, …), in the person's time zone.
 */
export function reportPeriod(kind: ReportKind, offset: number, now: Date, timeZone: string, locale: string): ReportPeriod {
  const today = localDateKey(now, timeZone);
  let startDate: LocalDate;
  let endDate: LocalDate;
  if (kind === 'weekly') {
    const monday = addDays(today, -((weekdayOf(today) + 6) % 7));
    startDate = addDays(monday, 7 * offset);
    endDate = addDays(startDate, 6);
  } else {
    const { year, month } = parseLocalDate(today);
    const index = month - 1 + offset;
    const y = year + Math.floor(index / 12);
    const m = (((index % 12) + 12) % 12) + 1;
    startDate = formatLocalDateKey(y, m, 1);
    const nextFirst = m === 12 ? formatLocalDateKey(y + 1, 1, 1) : formatLocalDateKey(y, m + 1, 1);
    endDate = addDays(nextFirst, -1);
  }
  const start = startOfLocalDay(startDate, timeZone).getTime();
  const end = startOfLocalDay(addDays(endDate, 1), timeZone).getTime();
  const label =
    kind === 'weekly'
      ? `${formatLocalDate(startDate, locale, { day: 'numeric', month: 'short' })} – ${formatLocalDate(endDate, locale, { day: 'numeric', month: 'short', year: 'numeric' })}`
      : formatLocalDate(startDate, locale, { month: 'long', year: 'numeric' });
  return { kind, startDate, endDate, start, end, label, complete: end <= now.getTime() };
}

export interface ReportRow {
  at: string;
  value: string;
  context: string | null;
  status: string | null;
  attention: boolean;
  notes: string | null;
}

export interface MarkerSummary {
  type: ReportMarker;
  label: string;
  unit: string;
  count: number;
  daysLogged: number;
  average: string | null;
  previousAverage: string | null;
  lowest: string | null;
  highest: string | null;
  /** Readings compared with a target (the clinician's, or the general reference range). */
  target: { within: number; above: number; below: number; assessed: number; source: string } | null;
  attention: number;
  trend: string | null;
  /** Blood sugar only: averages by when it was taken (fasting, after meals…). */
  contexts: { label: string; count: number; average: string }[];
  points: SparkPoint[];
  rows: ReportRow[];
}

export interface MarkerReport {
  kind: ReportKind;
  period: ReportPeriod;
  previous: ReportPeriod;
  profileName: string;
  generatedAt: string;
  markers: MarkerSummary[];
}

const inPeriod = (r: VitalReading, p: ReportPeriod) => {
  const t = Date.parse(r.measuredAt);
  return t >= p.start && t < p.end;
};

function averageText(type: ReportMarker, rs: VitalReading[], profile: Profile): string | null {
  if (!rs.length) return null;
  if (type === 'blood_pressure') {
    return `${Math.round(mean(rs.map((r) => r.systolic as number)) as number)}/${Math.round(mean(rs.map((r) => r.diastolic as number)) as number)}`;
  }
  return formatDisplay('glucose', mean(rs.map((r) => toDisplay('glucose', r.valueCanonical as number, profile))) as number, profile);
}

/** The value used for ordering and trends: systolic for blood pressure, mg/dL for blood sugar. */
const keyValue = (r: VitalReading) => (r.type === 'blood_pressure' ? (r.systolic as number) : (r.valueCanonical as number));

export function summarizeMarker(
  type: ReportMarker,
  readings: VitalReading[],
  previousReadings: VitalReading[],
  targets: ClinicianTarget[],
  profile: Profile,
  timeZone: string,
  locale: string,
): MarkerSummary {
  const rs = readings.filter((r) => r.type === type).sort((a, b) => Date.parse(a.measuredAt) - Date.parse(b.measuredAt));
  const prev = previousReadings.filter((r) => r.type === type);
  const label = VITAL_META[type].label;
  const unit = displayUnit(type, profile);

  let within = 0;
  let above = 0;
  let below = 0;
  let assessed = 0;
  let attention = 0;
  const sources = new Set<'clinician' | 'reference'>();
  const rows: ReportRow[] = rs.map((r) => {
    const a = assessReading(r, targets, profile.emergencyNumber);
    if (a.position && a.target) {
      assessed++;
      if (a.position === 'within') within++;
      else if (a.position === 'above') above++;
      else below++;
      sources.add(a.target.source === 'clinician' ? 'clinician' : 'reference');
    }
    if (a.escalation) attention++;
    const pill = positionPill(a.position, a.target);
    return {
      at: formatDateTime(r.measuredAt, timeZone, locale, { weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }),
      value: readingDisplay(r, profile).value + (r.type === 'blood_pressure' && r.pulse ? ` · pulse ${r.pulse}` : ''),
      context: contextLabel(r.context),
      status: pill?.label ?? null,
      attention: !!a.escalation,
      notes: r.notes?.trim() ? r.notes.trim() : null,
    };
  });

  const sorted = [...rs].sort((a, b) => keyValue(a) - keyValue(b));
  const lowest = sorted.length ? readingDisplay(sorted[0], profile).value : null;
  const highest = sorted.length ? readingDisplay(sorted[sorted.length - 1], profile).value : null;
  const trend = linearTrend(
    rs.map((r) => ({ t: Date.parse(r.measuredAt), v: keyValue(r) })),
    { stableThreshold: TREND_THRESHOLD[type] },
  );

  const contexts: MarkerSummary['contexts'] = [];
  if (type === 'glucose') {
    const groups = new Map<string, VitalReading[]>();
    for (const r of rs) {
      const key = contextLabel(r.context) ?? 'Not noted';
      groups.set(key, [...(groups.get(key) ?? []), r]);
    }
    for (const [ctx, group] of groups) contexts.push({ label: ctx, count: group.length, average: averageText('glucose', group, profile) as string });
  }

  return {
    type,
    label,
    unit,
    count: rs.length,
    daysLogged: new Set(rs.map((r) => localDateKey(Date.parse(r.measuredAt), timeZone))).size,
    average: averageText(type, rs, profile),
    previousAverage: averageText(type, prev, profile),
    lowest,
    highest,
    target: assessed
      ? {
          within,
          above,
          below,
          assessed,
          // Say exactly what the readings were compared with; blood sugar can mix both.
          source:
            sources.size > 1
              ? 'your clinician’s targets and general reference ranges'
              : sources.has('clinician')
                ? 'your clinician’s target'
                : 'the general reference range (not personalised)',
        }
      : null,
    attention,
    trend: trendWords(trend.direction)?.label ?? null,
    contexts,
    points: rs.map((r) =>
      type === 'blood_pressure'
        ? { t: Date.parse(r.measuredAt), v: r.systolic as number, v2: r.diastolic as number }
        : { t: Date.parse(r.measuredAt), v: toDisplay('glucose', r.valueCanonical as number, profile) },
    ),
    rows,
  };
}

/** `readings` must cover both the period and the previous one (for the comparison). */
export function buildMarkerReport(input: {
  period: ReportPeriod;
  previous: ReportPeriod;
  readings: VitalReading[];
  targets: ClinicianTarget[];
  profile: Profile;
  timeZone: string;
  locale: string;
  now: Date;
}): MarkerReport {
  const { period, previous, readings, targets, profile, timeZone, locale, now } = input;
  const current = readings.filter((r) => inPeriod(r, period));
  const before = readings.filter((r) => inPeriod(r, previous));
  return {
    kind: period.kind,
    period,
    previous,
    profileName: profile.displayName,
    generatedAt: formatDateTime(now.toISOString(), timeZone, locale, { dateStyle: 'medium', timeStyle: 'short' }),
    markers: REPORT_MARKERS.map((m) => summarizeMarker(m, current, before, targets, profile, timeZone, locale)),
  };
}

const periodWord = (kind: ReportKind) => (kind === 'weekly' ? 'week' : 'month');

export function reportTitle(report: MarkerReport): string {
  return `${report.kind === 'weekly' ? 'Weekly' : 'Monthly'} report: ${report.period.label}`;
}

export function reportFileName(report: MarkerReport): string {
  return `FAITH-${report.kind}-report-${report.period.startDate}-to-${report.period.endDate}.pdf`;
}

/** One-paragraph summary of a marker, used in the email body and the PDF. */
export function markerSentence(m: MarkerSummary, kind: ReportKind): string {
  if (!m.count) return `${m.label}: no readings this ${periodWord(kind)}.`;
  const parts = [`${m.label}: ${m.count} reading${m.count === 1 ? '' : 's'} on ${m.daysLogged} day${m.daysLogged === 1 ? '' : 's'}.`];
  parts.push(`Average ${m.average} ${m.unit}${m.previousAverage ? ` (previous ${periodWord(kind)} ${m.previousAverage})` : ''}.`);
  if (m.count > 1) parts.push(`Lowest ${m.lowest}, highest ${m.highest}.`);
  if (m.target) parts.push(`${m.target.within} of ${m.target.assessed} within ${m.target.source}.`);
  if (m.trend) parts.push(`Trend: ${m.trend.toLowerCase()}.`);
  if (m.attention) parts.push(`${m.attention} reading${m.attention === 1 ? '' : 's'} needed attention.`);
  return parts.join(' ');
}

export const REPORT_DISCLAIMER =
  'Prepared by FAITH AI from the readings recorded on this phone, exactly as they were entered. It is a personal record, not a medical document or diagnosis. Bring it to your next check-up and discuss any changes with your clinician.';

export function reportEmailBody(report: MarkerReport, withAttachment: boolean): string {
  const lines = [
    `FAITH AI ${report.kind} report: blood pressure and blood sugar`,
    `${report.profileName} · ${report.period.label}${report.period.complete ? '' : ' (so far)'}`,
    '',
    ...report.markers.map((m) => markerSentence(m, report.kind)),
    '',
    withAttachment ? 'The full report with every reading is attached as a PDF.' : 'Open FAITH to print or save the full report with every reading.',
    '',
    REPORT_DISCLAIMER,
  ];
  return lines.join('\n');
}

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const TEAL = '#0F7D73';
const LAVENDER = '#7C5CD6';

function chartSvg(m: MarkerSummary, period: ReportPeriod): string {
  const W = 515;
  const H = 96;
  const g = sparkGeometry(m.points, W, H, { start: period.start, end: period.end }, 8);
  if (!g) return '';
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${esc(m.label)} trend">
    <path d="${g.area}" fill="${TEAL}" fill-opacity="0.08" />
    ${g.line2 ? `<path d="${g.line2}" fill="none" stroke="${LAVENDER}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" />` : ''}
    <path d="${g.line}" fill="none" stroke="${TEAL}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round" />
  </svg>
  <p class="axis"><span>${esc(formatLocalDate(period.startDate, 'en', { day: 'numeric', month: 'short' }))}</span>${m.type === 'blood_pressure' ? `<span><i class="key" style="background:${TEAL}"></i>Top (systolic) <i class="key" style="background:${LAVENDER}"></i>Bottom (diastolic)</span>` : ''}<span>${esc(formatLocalDate(period.endDate, 'en', { day: 'numeric', month: 'short' }))}</span></p>`;
}

function markerSection(m: MarkerSummary, report: MarkerReport): string {
  if (!m.count) {
    return `<section><h2>${esc(m.label)}</h2><p class="empty">No ${esc(m.label.toLowerCase())} readings were recorded this ${periodWord(report.kind)}.</p></section>`;
  }
  const tiles = [
    ['Average', `${m.average} <small>${esc(m.unit)}</small>`],
    [`Previous ${periodWord(report.kind)}`, m.previousAverage ? `${m.previousAverage} <small>${esc(m.unit)}</small>` : '<small>No readings</small>'],
    ['Lowest – highest', m.count > 1 ? `${m.lowest} – ${m.highest}` : `${m.lowest}`],
    ['Within target', m.target ? `${m.target.within} of ${m.target.assessed}` : '<small>No target</small>'],
  ]
    .map(([k, v]) => `<div class="tile"><span>${k}</span><b>${v}</b></div>`)
    .join('');
  const contexts = m.contexts.length
    ? `<p class="note">${m.contexts.map((c) => `${esc(c.label)}: average ${esc(c.average)} (${c.count})`).join(' · ')}</p>`
    : '';
  const rows = m.rows
    .map(
      (r) =>
        `<tr${r.attention ? ' class="attention"' : ''}><td>${esc(r.at)}</td><td class="num">${esc(r.value)}</td><td>${esc(r.context ?? '')}</td><td>${esc(r.status ?? '')}${r.attention ? ' · needs attention' : ''}${r.notes ? `<div class="notes">${esc(r.notes)}</div>` : ''}</td></tr>`,
    )
    .join('');
  return `<section>
  <h2>${esc(m.label)} <small>${m.count} reading${m.count === 1 ? '' : 's'} on ${m.daysLogged} day${m.daysLogged === 1 ? '' : 's'}${m.trend ? ` · Trend: ${esc(m.trend)}` : ''}</small></h2>
  <div class="tiles">${tiles}</div>
  ${chartSvg(m, report.period)}
  ${m.target ? `<p class="note">Compared with ${esc(m.target.source)}: ${m.target.within} within, ${m.target.above} above, ${m.target.below} below.${m.attention ? ` ${m.attention} reading${m.attention === 1 ? '' : 's'} needed attention.` : ''}</p>` : ''}
  ${contexts}
  <table><thead><tr><th>When</th><th>Reading (${esc(m.unit)})</th><th>Context</th><th>Note</th></tr></thead><tbody>${rows}</tbody></table>
</section>`;
}

/** Print-ready HTML (A4), rendered to PDF on the phone. System fonts only, no external resources. */
export function reportHtml(report: MarkerReport): string {
  return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(reportTitle(report))}</title><style>
  @page { size: A4; margin: 18mm 16mm; }
  * { box-sizing: border-box; }
  body { font-family: -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; color: #12211F; font-size: 11pt; line-height: 1.45; margin: 0; }
  header { border-bottom: 3px solid ${TEAL}; padding-bottom: 10px; margin-bottom: 14px; }
  header .brand { color: ${TEAL}; font-weight: 800; letter-spacing: 0.04em; font-size: 10pt; text-transform: uppercase; }
  h1 { font-size: 19pt; margin: 4px 0 2px; letter-spacing: -0.02em; }
  header p { margin: 0; color: #3E5552; }
  h2 { font-size: 14pt; margin: 18px 0 8px; color: ${TEAL}; }
  h2 small { font-size: 10pt; color: #546B68; font-weight: 500; }
  .tiles { display: flex; gap: 8px; }
  .tile { flex: 1; border: 1px solid #DFE8E6; border-radius: 10px; padding: 8px 10px; }
  .tile span { display: block; font-size: 8.5pt; color: #546B68; text-transform: uppercase; letter-spacing: 0.05em; }
  .tile b { font-size: 14pt; font-variant-numeric: tabular-nums; }
  .tile small { font-size: 9pt; color: #546B68; font-weight: 500; }
  .chart { display: block; margin: 10px 0 0; width: 100%; height: auto; }
  .axis { display: flex; justify-content: space-between; font-size: 8.5pt; color: #546B68; margin: 2px 0 6px; }
  .key { display: inline-block; width: 12px; height: 3px; border-radius: 2px; vertical-align: middle; margin: 0 4px 0 8px; }
  .note { font-size: 9.5pt; color: #3E5552; margin: 4px 0; }
  .empty { color: #546B68; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; font-size: 9.5pt; }
  th { text-align: left; font-size: 8.5pt; color: #546B68; text-transform: uppercase; letter-spacing: 0.04em; border-bottom: 1.5px solid #DFE8E6; padding: 5px 6px; }
  td { padding: 5px 6px; border-bottom: 1px solid #EDF3F2; vertical-align: top; }
  tr { page-break-inside: avoid; }
  td.num { font-variant-numeric: tabular-nums; font-weight: 700; white-space: nowrap; }
  tr.attention td { background: #FDE8EA; }
  .notes { color: #546B68; font-size: 8.5pt; margin-top: 2px; }
  .summary { background: #EDF3F2; border-radius: 10px; padding: 10px 12px; margin: 0 0 6px; }
  .summary p { margin: 2px 0; }
  footer { margin-top: 18px; padding-top: 8px; border-top: 1px solid #DFE8E6; font-size: 8.5pt; color: #546B68; }
</style></head><body>
<header>
  <div class="brand">FAITH AI · ${report.kind === 'weekly' ? 'Weekly' : 'Monthly'} report</div>
  <h1>Blood pressure and blood sugar</h1>
  <p>${esc(report.profileName)} · ${esc(report.period.label)}${report.period.complete ? '' : ' (so far)'} · Prepared ${esc(report.generatedAt)}</p>
</header>
<div class="summary">${report.markers.map((m) => `<p>${esc(markerSentence(m, report.kind))}</p>`).join('')}</div>
${report.markers.map((m) => markerSection(m, report)).join('\n')}
<footer>${esc(REPORT_DISCLAIMER)}</footer>
</body></html>`;
}
